
import React, { useState, useEffect } from 'react';
import { HashRouter as Router } from 'react-router-dom';
import HtmlDialog from './HtmlDialog';
import VariantDialog from './VariantDialog';
import AlertModal from './AlertModal';
import rolesData from './rolesData';
import preData from './preData'; // Importation du fichier preData.js
import './App.css';

function App() {
  const [submittedText, setSubmittedText] = useState('');
  const [selectedActions, setSelectedActions] = useState([]);
  const [executedActions, setExecutedActions] = useState([]);
  const [showActions, setShowActions] = useState(false);
  const [displayResult, setDisplayResult] = useState(false);
  const [variantDialogVisible, setVariantDialogVisible] = useState(false);
  const [actionResults, setActionResults] = useState({});
  const [variantCount, setVariantCount] = useState('');
  const [alertMessage, setAlertMessage] = useState('');
  const [actionsData, setActionsData] = useState([]);
  const [highlightCopyButton, setHighlightCopyButton] = useState(false);
  const [defaultText, setDefaultText] = useState('');
  const [showPopup, setShowPopup] = useState(true);
  const [preText, setPreText] = useState(''); // Nouveau state pour stocker le texte préfixe

  useEffect(() => {
    const urlParams = new URLSearchParams(window.location.search);
    const version = urlParams.get('version') || '-offre1'; // suffixe du nom du fichier actionsData
    const role = urlParams.get('role') || '700'; // Mission dans le rôle de leadership pour 600
    const param = urlParams.get('param');
    const pre = urlParams.get('pre')||'700'; // ---
    if (param !== 'nok') {
      setShowPopup(false);
    }

    // Chercher le texte correspondant au numéro "pre" et le stocker dans preText
    if (pre) {
      const preDataItem = preData.find(p => p.no === parseInt(pre));
      if (preDataItem) {
        setPreText(preDataItem.texte1);
      }
    }

    import(`./actionsData${version}.js`).then(module => {
      setActionsData(module.default);
    }).catch(err => {
      console.error('Failed to load actions data:', err);
    });

    const selectedRole = rolesData.find(r => r.no === parseInt(role)) || rolesData[0];
    setDefaultText(selectedRole.texte1);

  }, []);

  const handleSubmit = (text) => {
    setSubmittedText(text);
    setShowActions(true);
    setDisplayResult(false);
    console.log('Texte soumis :', text);
  };

  const handleCheckboxChange = (e) => {
    const actionNo = parseInt(e.target.value);
    if (e.target.checked) {
      setSelectedActions([...selectedActions, actionNo]);
    } else {
      setSelectedActions(selectedActions.filter(no => no !== actionNo));
    }
  };

  const handleActionsSubmitAndCopy = (e) => {
    e.preventDefault();
    setShowActions(false);
    setDisplayResult(true);
    setHighlightCopyButton(true);
    console.log('Actions demandées :', selectedActions);

    const newExecutedActions = [...executedActions];

    selectedActions.forEach(actionNo => {
      const action = actionsData.find(a => a.no === actionNo);
      if (action && action.fonction && functionsMap[action.fonction]) {
        functionsMap[action.fonction](submittedText);
      }
      newExecutedActions.push(actionNo);
    });

    setExecutedActions(newExecutedActions);
    setSelectedActions([]);

    // Combiner la logique de copie ici
    let actionsChosen = newExecutedActions.map((actionNo, index) => {
      const action = actionsData.find(action => action.no === actionNo);
      let actionResult = '';

      if (action.fonction === 'proposeVariants' && variantCount) {
        actionResult = `${variantCount} `;
      } else if (action.fonction && actionResults[action.fonction]) {
        actionResult = actionResults[action.fonction];
      }

      return `${index + 1}. ${action.action.replace('{n}', actionResult)}`;
    }).join('\n');

    // Ajout du préfixe au texte à copier
    const textToCopy = `${preText}------------ \n${submittedText}\n\nTasks:\n${actionsChosen}\n\n-------------\nAs-tu bien compris ?\n\nY aurait-il quelque chose d’important que j’aurais oublié ?\n\nDe quelles informations aurais-tu encore besoin pour mieux répondre à ma requête ?\n\nPrends ton temps pour répondre, c’est la qualité de ta réponse qui prime.\n\nMaintenant, respire profondément et à partir de la demande qui t'a été soumise, exécute scrupuleusement les actions à effectuer les unes après les autres. \n\nC’est vraiment important pour mon avenir ! \n\nMerci pour ton temps et pour la qualité de ta réponse 💯  ✨`;

    navigator.clipboard.writeText(textToCopy).then(() => {
      if (showPopup) {
        setAlertMessage('BIEN \nTon ordre de mission est maintenant dans le presse-papier.  \n\nTu peux le soumettre à tes IA préférées.   \n\nVérifie les réponses avec plusieurs autres IA, sinon gare aux hallucinations !\n\nPlusieurs avis valent mieux qu´un !\n\nRelis attentivement les réponses des IA.\nExamine chaque étape des actions proposées.\n\nSi quelque chose n\'est pas clair, n´hésite pas à interroger les IA.\n\nLa qualité de la réponse dépend de la précision et de la clarté de ta demande.\n');
      } else {
        window.location.href = 'https://sites.google.com/view/satia-ia/multi-ia';
      }
    });
  };

  const proposeVariants = (text) => {
    setVariantDialogVisible(true);
  };

  const handleVariantSubmit = (count) => {
    setActionResults(prevResults => ({
      ...prevResults,
      proposeVariants: count,
    }));
    setVariantCount(count);
    setVariantDialogVisible(false);
  };

  const functionsMap = {
    proposeVariants,
  };

  return (
    <Router>
      <div className="App three-column-margin">
        <HtmlDialog onSubmit={handleSubmit} defaultText={defaultText} />
        {submittedText && (
          <div>
            <h2>Draft soumis :</h2>
            <pre>{submittedText}</pre>
          </div>
        )}
        {showActions && (
          <div>
            <h2>Actions :</h2>
            <form onSubmit={handleActionsSubmitAndCopy}>
              {actionsData.map(action => {
                const isActionExecuted = executedActions.includes(action.no);
                const isFunctionExecuted = action.fonction && executedActions.some(no => actionsData.find(a => a.no === no && a.fonction === action.fonction));
                return (
                 // <div key={action.no}>

                 <div key={action.no} style={{ marginBottom: '0.5em' }}> {/* Ajout d'un espacement d'une demi-ligne */}

                    <label>
                      <input
                        type="checkbox"
                        value={action.no}
                        onChange={handleCheckboxChange}
                        disabled={isActionExecuted || isFunctionExecuted}
                      />
                      {action.action
                      .replace('{n}', actionResults[action.fonction] || '')

                      .split('\n') // Divise le texte là où il y a des sauts de ligne
                      .map((line, index) => (
                        <span key={index}>
                          {line}
                          <br />
                          </span>                   
                          ))}



                    </label>
                  </div>
                );
              })}
              <hr />
              <div style={{ display: 'flex', justifyContent: 'flex-start', gap: '10px', margin: '10px 0' }}>
                <button type="submit" style={{
                  padding: '10px 20px',
                  fontSize: '16px',
                  backgroundColor: '#4CAF50',
                  color: 'white',
                  border: 'none',
                  borderRadius: '4px',
                  cursor: 'pointer'
                }}>
                  3. Soumets les actions aux IA
                </button>
                <div style={{ width: '30%', backgroundColor: '#f2f2f2', padding: '10px', fontStyle: 'italic' }}>
                Après avoir choisi les actions à déléguer aux IA (2 à 5 tâches par itération selon la puissance de l'IA).  <br />Clic sur ce bouton pour copier la mission dans le presse-papier.<br />Ensuite copier-coller dans les IA.<br />En y joignant les pièces (documents, images) adéquates.

                </div>
              </div>
            </form>
          </div>
        )}
        {displayResult && (
          <div>
            <h2>Actions à effectuer :</h2>
            <ol>
              {executedActions.map((actionNo, index) => (
                <li key={actionNo}>
                  {actionsData.find(action => action.no === actionNo).action}
                  {actionsData.find(action => action.no === actionNo).fonction && (
                    <span>: {actionResults[actionsData.find(action => action.no === actionNo).fonction]}</span>
                  )}
                </li>
              ))}
            </ol>
          </div>
        )}
        {variantDialogVisible && (
          <VariantDialog onSubmit={handleVariantSubmit} />
        )}
        {alertMessage && (
          <AlertModal
            message={alertMessage}
            onClose={() => {
              setAlertMessage('');
              window.location.href = 'https://sites.google.com/view/satia-ia/multi-ia';
            }}
          />
        )}
      </div>
    </Router>
  );
}

export default App;

